// Define the enumeration representing possible data types
#[derive(Debug, PartialEq, Eq)]
enum DataType {
    ScalarInt,
    ScalarFloat,
    ScalarComplex,
    ScalarBool,
    ScalarString,
    ArrayType,
    CompositeType,
    UnknownType,
}

// Function to check if a DataType variant represents a scalar type
fn issctype(rep: DataType) -> bool {
    match rep {
        DataType::ScalarInt
        | DataType::ScalarFloat
        | DataType::ScalarComplex
        | DataType::ScalarBool
        | DataType::ScalarString => true,
        _ => false,
    }
}

// Example usage and tests
fn main() {
    // Test scalar types
    assert!(issctype(DataType::ScalarInt));
    assert!(issctype(DataType::ScalarFloat));
    assert!(issctype(DataType::ScalarComplex));
    assert!(issctype(DataType::ScalarBool));
    assert!(issctype(DataType::ScalarString));
    
    // Test non-scalar types
    assert!(!issctype(DataType::ArrayType));
    assert!(!issctype(DataType::CompositeType));
    assert!(!issctype(DataType::UnknownType));
    
    println!("All tests passed!");
}